<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">bbtex</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> results</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> paper.tex</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">                    # diagnostics from the last log</span></span>
